package com.example.doctoolkit.ui;
import android.app.*; import android.content.*; import android.net.Uri; import android.os.*; import android.widget.*; import com.example.doctoolkit.R; import com.example.doctoolkit.data.*; import com.example.doctoolkit.network.*; import java.io.*; import okhttp3.*; import retrofit2.*; import retrofit2.converter.scalars.ScalarsConverterFactory;
public class UploadActivity extends Activity { Call<ResponseBody> call; ProgressBar bar; public void onCreate(Bundle b){super.onCreate(b); setContentView(R.layout.activity_upload); bar=findViewById(R.id.progressBar); findViewById(R.id.cancelButton).setOnClickListener(v->{ if(call!=null)call.cancel(); finish();}); upload(); }
 private void upload(){ Uri uri=getIntent().getData(); String tool=getIntent().getStringExtra("tool"), name=getIntent().getStringExtra("name"); BackendApi api=new Retrofit.Builder().baseUrl("http://10.0.2.2:8080/").addConverterFactory(ScalarsConverterFactory.create()).build().create(BackendApi.class); ProgressRequestBody body=new ProgressRequestBody(this,uri,"application/octet-stream",p->runOnUiThread(()->bar.setProgress(p))); MultipartBody.Part file=MultipartBody.Part.createFormData("file",name,body); RequestBody fmt=RequestBody.create("pdf",MediaType.parse("text/plain")); if("compress".equals(tool)) call=api.compress(file); else if("split".equals(tool)) call=api.split(file,RequestBody.create("1-1",MediaType.parse("text/plain"))); else if("ocr".equals(tool)) call=api.ocr(file,RequestBody.create("eng+hin+mar",MediaType.parse("text/plain"))); else call=api.convert(file,fmt); call.enqueue(new Callback<ResponseBody>(){ public void onResponse(Call<ResponseBody> c, Response<ResponseBody> r){ try{File out=new File(getCacheDir(), "result_"+System.currentTimeMillis()); try(InputStream in=r.body().byteStream(); FileOutputStream fos=new FileOutputStream(out)){byte[] buf=new byte[8192]; for(int n;(n=in.read(buf))!=-1;)fos.write(buf,0,n);} new Thread(()->{AppDatabase db=AppDatabase.get(UploadActivity.this); db.historyDao().insert(new HistoryItem(tool,name,out.getName(),out.getAbsolutePath(),System.currentTimeMillis())); db.historyDao().trim();}).start(); startActivity(new Intent(UploadActivity.this,ResultActivity.class).putExtra("path",out.getAbsolutePath())); finish();}catch(Exception e){toast(e.getMessage());}} public void onFailure(Call<ResponseBody> c, Throwable t){toast(t.getMessage());}});} void toast(String s){runOnUiThread(()->Toast.makeText(this,s,Toast.LENGTH_LONG).show());} }
